{"Channel": {"name": "planning-imentAIX", "channelID": "ch-ntaix-141b6b"}, "Message": {"User": {"userId": "eid_eb1756e0", "timestamp": "2026-03-31T02:43:00", "text": "Hi team, QA team found some issues in the last release of imentAIX. The report came from QA Specialist eid_7b874c82.", "utterranceID": "20260328-0-772bb"}, "Reactions": []}, "ThreadReplies": [], "id": "20260328-0-772bb"}
