{"Channel": {"name": "bug-bobdavis-PersonalizeForce", "channelID": "ch-force-cdb98a"}, "Message": {"User": {"userId": "eid_83b716d4", "timestamp": "2026-12-11T04:02:00", "text": "Hi team, the bug titled 'API Rate Limiting Causes Delayed Responses' has been resolved. You can check the details in the approved PR here: https://github.com/salesforce/PersonalizeForce/pull/42.", "utterranceID": "20261210-0-d7600"}, "Reactions": []}, "ThreadReplies": [], "id": "20261210-0-d7600"}
