{"Channel": {"name": "develop-hannahmiller-PitchForce", "channelID": "ch--paix-42f139"}, "Message": {"User": {"userId": "eid_4de5cd7f", "timestamp": "2026-10-30T08:56:00", "text": "That sounds serious. @eid_8df92d08, could you shed some light on these issues? Were these scenarios considered during development?", "utterranceID": "20261030-3-a50df"}, "Reactions": []}, "ThreadReplies": [], "id": "20261030-3-a50df"}
