{"Channel": {"name": "develop-emmagarcia-ContentForce", "channelID": "ch-force-b24c79"}, "Message": {"User": {"userId": "eid_b814ccfb", "timestamp": "2026-04-19T20:43:00", "text": "Let's proceed with reverting. @eid_5549aeb7, can you handle that?", "utterranceID": "20260419-10-224df"}, "Reactions": []}, "ThreadReplies": [], "id": "20260419-10-224df"}
