{"Channel": {"name": "develop-emmagarcia-ContentForce", "channelID": "ch-force-b24c79"}, "Message": {"User": {"userId": "eid_5549aeb7", "timestamp": "2026-04-25T16:51:00", "text": "Hi team, please check my PR for adding visual indicators to drag-and-drop actions: https://github.com/salesforce/ContentForce/pull/6. The goal is to enhance the user experience by highlighting the widget being dragged and clearly indicating potential drop zones. Let me know your thoughts! 😊", "utterranceID": "20260426-0-26e1a"}, "Reactions": []}, "ThreadReplies": [], "id": "20260426-0-26e1a"}
