{"Channel": {"name": "planning-extAIX", "channelID": "ch-xtaix-274901"}, "Message": {"User": {"userId": "eid_c7622c8e", "timestamp": "2026-09-05T02:06:00", "text": "Hi team, one of the common issues reported for extAIX is that the user interface can be overwhelming for new users. This was reported by Customer ID: CUST-0013.", "utterranceID": "20260829-0-72190"}, "Reactions": []}, "ThreadReplies": [], "id": "20260829-0-72190"}
